#!/usr/bin/env bash
# Question 11: Service for an external database. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

cat > /opt/cka-legacy-db.py <<'EOF'
import socket
s = socket.socket()
s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
s.bind(("0.0.0.0", 5432))
s.listen(16)
while True:
    c, _ = s.accept()
    c.sendall(b"legacy-db ok\n")
    c.close()
EOF
systemctl stop cka-legacy-db >/dev/null 2>&1 || true
systemctl reset-failed cka-legacy-db >/dev/null 2>&1 || true
systemd-run --unit cka-legacy-db --collect python3 /opt/cka-legacy-db.py >/dev/null
for _ in $(seq 1 20); do (exec 3<>/dev/tcp/127.0.0.1/5432) 2>/dev/null && break; sleep 1; done
kubectl create namespace "${Q11_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q11_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q11_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q11_NS}" delete service legacy-db --ignore-not-found >/dev/null
kubectl -n "${Q11_NS}" delete endpointslice -l kubernetes.io/service-name=legacy-db --ignore-not-found >/dev/null
kubectl apply -f - <<EOF >/dev/null
apiVersion: v1
kind: Pod
metadata:
  name: client
  namespace: ${Q11_NS}
  labels: { role: client }
spec:
  containers:
    - name: shell
      image: busybox:1.36
      command: ["sleep", "infinity"]
EOF
kubectl -n "${Q11_NS}" wait --for=condition=Ready pod/client --timeout=180s >/dev/null
: "${Q11_NS}" "${Q11_NODEPORT}"
